+/** Chooses `ko` or `en` from an Accept-Language header or headers map, falling back to `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const raw =
+    header && typeof header === "object"
+      ? Object.entries(header).find(([k]) => k.toLowerCase() === "accept-language")?.[1]
+      : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  const choices = [];
+  for (const part of raw.split(",")) {
+    const [tagPart, ...params] = part.trim().split(";");
+    const primary = tagPart.trim().toLowerCase().split(/[-_]/)[0];
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p.trim());
+      if (m) {
+        q = Number(m[1]);
+        if (!Number.isFinite(q) || q < 0 || q > 1) valid = false;
+      }
+    }
+    if (valid && q > 0 && LANGUAGES.includes(primary)) choices.push({ lang: primary, q });
+  }
+  choices.sort((a, b) => b.q - a.q);
+  return choices[0]?.lang ?? fallback;
+}
